window.PORTAL={"day": 5, "title": "Mechanical Ventilation + ABG + BPD + Air-Leak Syndromes", "docTitle": "DAY 5 MECHANICAL VENTILATION + ABG + BPD + AIR-LEAK SYNDROMES", "subtitle": ["NEET-SS + ICP Paediatrics 2026 Master Course", "Premium 4-hour postgraduate module • 75 original MCQs • Day 3/Day 5 swap preserved"], "source": "source/Day_5_NEET_SS_ICP_Paediatrics_2026_Premium_Final_v2.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "<strong>NEET-SS + ICP Paediatrics 2026 Master Course</strong>"}, {"t": "p", "html": "Premium 4-hour postgraduate module • 75 original MCQs • Day 3/Day 5 swap preserved"}, {"t": "callout", "label": "GUIDELINE CURRENCY CHECK", "title": "", "html": ["Respiratory-support principles were aligned with the 2025 AHA/AAP neonatal resuscitation guideline, 2025 ILCOR neonatal life-support consensus, European Consensus RDS guideline (2022 update, published 2023), contemporary BPD literature including Jensen respiratory-support grading at 36 weeks PMA, and current neonatal ventilation practice. Where evidence is not universal, concepts are labelled as pragmatic NICU practice rather than a single absolute threshold."], "fill": "17365D"}, {"t": "callout", "label": "DAY 5 EXAM MISSION", "title": "", "html": ["Control oxygenation and ventilation while minimizing lung and brain injury. Read the ventilator and blood gas together, identify the physiological problem, make the smallest effective change, recognize ventilator-induced lung injury and BPD risk, and diagnose/treat neonatal air leak before deterioration."], "fill": "17365D"}]}, {"title": "Learning Objectives", "h1": "Learning Objectives", "blocks": [{"t": "list", "ordered": false, "items": ["Explain pressure, flow, volume, compliance, resistance, time constant, mean airway pressure and oxygenation/ventilation determinants.", "Interpret common neonatal invasive modes: pressure-controlled, SIMV, assist-control, volume-targeted ventilation, PSV concepts and HFOV.", "Select initial ventilator settings according to disease physiology rather than memorizing a single recipe.", "Use blood gases systematically to diagnose acute and compensated respiratory/metabolic disorders.", "Perform ABG calculations including anion gap, compensation and oxygenation index.", "Troubleshoot hypoxemia, hypercapnia, hypocapnia, ventilator asynchrony and sudden deterioration.", "Apply lung-protective ventilation, permissive hypercapnia and avoidance of hypocapnia in preterm infants.", "Define and classify BPD using historical and contemporary respiratory-support based systems.", "Recognize BPD pathogenesis, prevention, pulmonary hypertension risk and long-term respiratory consequences.", "Diagnose pneumothorax, PIE, pneumomediastinum and other air leaks; know when emergency decompression precedes imaging."]}]}, {"title": "4-Hour Teaching Plan", "h1": "4-Hour Teaching Plan", "blocks": [{"t": "table", "head": ["<strong>Time</strong>", "<strong>Focus</strong>"], "rows": [["00:00–00:35", "Ventilator physiology, compliance/resistance/time constants, oxygenation vs ventilation"], ["00:35–01:20", "Conventional ventilation modes, VTV, weaning, extubation, troubleshooting"], ["01:20–01:55", "ABG interpretation + calculations + ventilator adjustments"], ["01:55–02:20", "HFOV, refractory respiratory failure, oxygenation index"], ["02:20–02:55", "BPD definition, pathogenesis, prevention, treatment, pulmonary hypertension"], ["02:55–03:20", "Air-leak syndromes: pneumothorax, PIE, pneumomediastinum, emergency management"], ["03:20–03:50", "Progressive cases + data/ventilator-image style interpretation"], ["03:50–04:00", "MCQ strategy, rapid revision, error notebook"]]}]}]}, {"id": "part-1", "title": "Ventilator Physiology", "eyebrow": "Part I", "group": "Study Notes", "kind": "notes", "sections": [{"title": "1. Oxygenation vs Ventilation", "blocks": [{"t": "table", "head": ["<strong>Problem</strong>", "<strong>Main determinant</strong>", "<strong>Ventilator lever</strong>", "<strong>Common mistake</strong>"], "rows": [["Hypoxemia", "FiO2, mean airway pressure, recruitment, V/Q", "FiO2, PEEP, inspiratory time/MAP, recruitment", "Increasing rate for an oxygenation problem"], ["Hypercapnia", "Effective minute ventilation", "VT or driving pressure; rate; dead space", "Increasing FiO2 to treat CO2"], ["Hypocapnia", "Excess alveolar ventilation", "Reduce VT/driving pressure and/or rate", "Ignoring brain-injury risk"], ["Mixed failure", "Underlying mechanics + support", "Correct physiology first", "Changing many knobs simultaneously"]]}, {"t": "grid", "items": [{"label": "WHAT", "html": "Ventilator support controls gas exchange"}, {"label": "WHY", "html": "Oxygen and CO2 respond to different determinants"}, {"label": "HOW", "html": "Map abnormal gas to the correct mechanical variable"}, {"label": "RECOGNIZE", "html": "SpO2/PaO2 tell oxygenation; PaCO2 tells ventilation"}, {"label": "WHAT NEXT", "html": "Change one relevant variable and reassess"}]}]}, {"title": "2. Compliance, Resistance & Time Constant", "blocks": [{"t": "p", "html": "Compliance = ΔV/ΔP. Low-compliance disease such as RDS needs adequate distending pressure for a given tidal volume but remains vulnerable to volutrauma if pressure is used without tracking delivered volume."}, {"t": "p", "html": "Resistance is opposition to gas flow. Narrow airways, secretions and small ETTs increase resistance. Time constant τ = R × C. Approximately 3 time constants are required for ~95% filling/emptying and ~5 for near-complete equilibration."}, {"t": "table", "head": ["<strong>Physiology</strong>", "<strong>Time constant</strong>", "<strong>Ventilator implication</strong>"], "rows": [["RDS: low compliance", "Short", "Relatively short Ti can be adequate; avoid excessive pressures"], ["Obstructive airway disease / BPD", "Longer", "Need longer expiratory time to avoid gas trapping/auto-PEEP"], ["ETT obstruction/secretions", "Increased resistance", "Inspect tube/secretions before simply raising pressure"], ["Very compliant lungs", "Large VT for small ΔP", "VTV helps limit volutrauma"]]}, {"t": "callout", "label": "EXAM PEARL", "title": "", "html": ["Q1 pearl — PEEP: PEEP maintains FRC and reduces atelectatic shunt."], "fill": "17365D"}]}, {"title": "3. PIP, PEEP, Driving Pressure & Mean Airway Pressure", "blocks": [{"t": "table", "head": ["<strong>Variable</strong>", "<strong>Primary effect</strong>", "<strong>Too low</strong>", "<strong>Too high</strong>"], "rows": [["PIP / inspiratory pressure", "VT and CO2 clearance in pressure modes", "Low VT, hypercapnia", "Volutrauma/barotrauma, air leak"], ["PEEP", "FRC, recruitment, oxygenation", "Atelectasis, shunt", "Overdistension, impaired venous return"], ["ΔP = PIP − PEEP", "Driving pressure in pressure ventilation", "Inadequate VT", "Excess VT/lung injury"], ["Inspiratory time", "MAP/recruitment and delivered VT", "Incomplete inspiration", "Air trapping/hemodynamic effect if excessive"], ["Rate", "Minute ventilation", "Hypercapnia if too low", "Hypocapnia or air trapping if too high"], ["FiO2", "Inspired oxygen", "Hypoxemia", "Oxygen toxicity"]]}]}]}, {"id": "part-2", "title": "Conventional Mechanical Ventilation", "eyebrow": "Part II", "group": "Study Notes", "kind": "notes", "sections": [{"title": "4. When to Intubate / Use Invasive Ventilation", "blocks": [{"t": "list", "ordered": false, "items": ["Apnea, gasping or persistent bradycardia requiring effective PPV at birth.", "Failure of non-invasive support with worsening oxygenation, ventilation or fatigue.", "Severe recurrent apnea despite caffeine/non-invasive support.", "Need for procedures/transport where airway security is essential.", "Shock/neurologic depression with inadequate respiratory drive."]}, {"t": "callout", "label": "2025 AHA/AAP NRP-RELEVANT POINT", "title": "", "html": ["For newborns requiring ventilation, initial peak inflation pressures around 20–30 cm H2O are reasonable and should be adjusted to achieve effective ventilation. Excessive peak pressure can generate high tidal volume and is potentially harmful. Spontaneously breathing preterm infants needing respiratory support should preferentially receive CPAP rather than routine intubation."], "fill": "17365D"}]}, {"title": "5. Common Ventilator Modes", "blocks": [{"t": "table", "head": ["<strong>Mode</strong>", "<strong>How breaths are delivered</strong>", "<strong>Strength</strong>", "<strong>Pitfall</strong>"], "rows": [["SIMV pressure control", "Set synchronized mandatory breaths; spontaneous breaths between", "Common, allows spontaneous activity", "Unassisted breaths may increase work if no PS"], ["Assist-control", "Every qualifying spontaneous effort can trigger supported breath; backup rate", "Better synchrony/support", "Tachypnea may produce excessive supported rate"], ["Pressure support", "Patient-triggered, flow-cycled", "Useful with spontaneous breathing/weaning", "Not suitable when drive is unreliable"], ["Volume-targeted ventilation", "Pressure adjusts to target VT", "Reduces excessive VT", "Leaks/ETT characteristics affect measured VT"], ["HFOV", "Very small oscillatory VT around a set MAP", "Selected severe disease/air leak", "Requires separate MAP/amplitude/frequency logic"]]}]}, {"title": "6. Volume-Targeted Ventilation (VTV)", "blocks": [{"t": "callout", "label": "CORE", "title": "Why VTV matters", "html": ["Preterm lung compliance changes quickly after surfactant and recruitment. A fixed pressure can therefore deliver a rapidly changing VT. VTV adjusts pressure breath-to-breath toward a target VT."], "fill": "274E13"}, {"t": "callout", "label": "HIGH YIELD", "title": "Typical VT concept", "html": ["A target around 4–6 mL/kg is commonly used in preterm ventilation, individualized to disease, dead space and device. This is not a universal rigid number."], "fill": "7F6000"}, {"t": "callout", "label": "ADVANCED", "title": "Why VTV is protective", "html": ["Avoiding excessive VT is central because volutrauma may be more important than pressure alone. Evidence favors VTV over pressure-limited ventilation for several preterm outcomes."], "fill": "783F04"}]}, {"title": "7. Lung-Protective Ventilation", "blocks": [{"t": "list", "ordered": false, "items": ["Use non-invasive support when feasible and minimize invasive ventilation duration.", "Prefer volume-targeted ventilation or another lung-protective mode when conventional MV is required.", "Use the lowest effective FiO2 and pressure compatible with adequate gas exchange.", "Accept modest hypercapnia rather than aggressive ventilation if pH remains acceptable and the infant is stable.", "Avoid hypocapnia, especially PaCO2 &lt;35 mmHg, because of association with brain injury in preterm infants.", "European RDS guidance supports permissive hypercapnia during weaning if pH remains &gt;7.22.", "Use caffeine to facilitate liberation from MV in appropriate preterm infants."]}]}, {"title": "8. Practical Ventilator Adjustment Logic", "blocks": [{"t": "table", "head": ["<strong>Finding</strong>", "<strong>First question</strong>", "<strong>Likely adjustment</strong>"], "rows": [["Low PaO2, normal PaCO2", "Is lung recruited?", "Increase FiO2 acutely; optimize PEEP/MAP"], ["High PaCO2, low VT", "Is ventilation inadequate?", "Increase target VT/driving pressure or rate depending mechanics"], ["High PaCO2, adequate VT", "Dead space? obstruction? rate?", "Check ETT/secretions/circuit; consider rate"], ["Low PaCO2", "Too much minute ventilation?", "Reduce VT/driving pressure and/or rate"], ["Rising PaCO2 with hyperinflation", "Air trapping?", "Reduce rate, increase expiratory time"], ["Sudden desaturation + hypotension", "Air leak/ETT/circuit?", "DOPE; tension pneumothorax may need immediate decompression"]]}]}, {"title": "9. DOPE — Sudden Deterioration", "blocks": [{"t": "table", "head": ["<strong>Letter</strong>", "<strong>Cause</strong>", "<strong>Clue</strong>", "<strong>Immediate action</strong>"], "rows": [["D", "Displacement", "Tube depth changed, asymmetric chest rise", "Check ETT position"], ["O", "Obstruction", "High resistance, poor chest movement, secretions", "Suction/check kinking; replace ETT if needed"], ["P", "Pneumothorax", "Sudden hypoxemia/bradycardia, asymmetry", "If tension/unstable: immediate decompression"], ["E", "Equipment", "Disconnect, blocked circuit, ventilator malfunction", "Hand ventilate with known-good device"]]}]}, {"title": "10. Weaning & Extubation", "blocks": [{"t": "list", "ordered": false, "items": ["Correct the disease and reduce FiO2/pressure/VT support as compliance improves.", "Avoid chasing normal PaCO2 at the cost of injurious ventilation.", "Ensure adequate respiratory drive; caffeine is commonly used in very preterm infants.", "Assess spontaneous breathing, work of breathing, hemodynamic stability and secretion burden.", "Extubate to CPAP or NIPPV when ongoing non-invasive support is expected.", "Synchronised NIPPV after extubation can reduce reintubation in some preterm infants."]}, {"t": "callout", "label": "POSTNATAL CORTICOSTEROID HIGH-YIELD", "title": "", "html": ["In infants who remain ventilator-dependent after the first week and are at high BPD risk, a short low-dose dexamethasone course may be considered to facilitate extubation. Routine early high-dose dexamethasone is avoided; exact regimen follows NICU protocol and risk-benefit assessment."], "fill": "17365D"}]}]}, {"id": "part-3", "title": "ABG Interpretation", "eyebrow": "Part III", "group": "Study Notes", "kind": "notes", "sections": [{"title": "11. The 6-Step ABG Method", "blocks": [{"t": "list", "ordered": true, "items": ["Look at pH: acidemia (&lt;7.35) or alkalemia (&gt;7.45).", "Look at PaCO2: respiratory component.", "Look at HCO3− / base excess: metabolic component.", "Identify the primary disorder.", "Check expected compensation and mixed disorders.", "Link the ABG to ventilator, perfusion, lactate, electrolytes and clinical state."]}, {"t": "table", "head": ["<strong>Pattern</strong>", "<strong>pH</strong>", "<strong>PaCO2</strong>", "<strong>HCO3−</strong>", "<strong>Primary disorder</strong>"], "rows": [["Respiratory acidosis", "↓", "↑", "Normal early / ↑ chronic", "Hypoventilation"], ["Respiratory alkalosis", "↑", "↓", "Normal early / ↓ chronic", "Hyperventilation"], ["Metabolic acidosis", "↓", "Compensatory ↓", "↓", "Lactate, renal/GI loss, sepsis, shock, IEM"], ["Metabolic alkalosis", "↑", "Compensatory ↑", "↑", "Chloride depletion, diuretics, gastric losses"]]}]}, {"title": "12. Compensation Rules — Exam Use", "blocks": [{"t": "table", "head": ["<strong>Disorder</strong>", "<strong>Expected compensation</strong>"], "rows": [["Metabolic acidosis", "Winter: expected PaCO2 ≈ 1.5 × HCO3 + 8 ± 2"], ["Metabolic alkalosis", "PaCO2 rises ~0.5–0.7 mmHg per 1 mEq/L rise in HCO3 above normal"], ["Acute respiratory acidosis", "HCO3 rises ~1 mEq/L per 10 mmHg PaCO2 rise"], ["Chronic respiratory acidosis", "HCO3 rises ~3.5–4 mEq/L per 10 mmHg PaCO2 rise"], ["Acute respiratory alkalosis", "HCO3 falls ~2 mEq/L per 10 mmHg PaCO2 fall"], ["Chronic respiratory alkalosis", "HCO3 falls ~4–5 mEq/L per 10 mmHg PaCO2 fall"]]}, {"t": "callout", "label": "NEONATAL CAUTION", "title": "", "html": ["Compensation formulas are exam tools and physiologic approximations. Neonates may have evolving mixed disorders, especially with shock, renal immaturity and rapid ventilator changes."], "fill": "17365D"}]}, {"title": "13. Anion Gap & Delta Thinking", "blocks": [{"t": "p", "html": "Anion gap = Na − (Cl + HCO3). The laboratory's normal range matters and hypoalbuminemia lowers the expected AG."}, {"t": "table", "head": ["<strong>AG acidosis</strong>", "<strong>Examples</strong>"], "rows": [["High AG", "Lactate, renal failure, organic acidemias, selected ketoacidoses"], ["Normal AG", "Diarrhea, renal tubular acidosis, saline-related hyperchloremia"]]}]}, {"title": "14. Ventilator Changes from ABG", "blocks": [{"t": "table", "head": ["<strong>ABG</strong>", "<strong>Interpretation</strong>", "<strong>Typical next step</strong>"], "rows": [["7.20 / 70 / 27", "Respiratory acidosis", "Improve alveolar ventilation after checking ETT/circuit/mechanics"], ["7.50 / 27 / 21", "Respiratory alkalosis", "Reduce minute ventilation"], ["7.22 / 32 / 13", "Metabolic acidosis with compensation", "Treat perfusion/metabolic cause"], ["7.10 / 65 / 19", "Mixed respiratory + metabolic acidosis", "Address ventilation and systemic problem"], ["Normal pH / high CO2 / high HCO3", "Compensated chronic respiratory acidosis", "Avoid abrupt over-normalization"]]}]}]}, {"id": "part-4", "title": "High-Frequency Oscillatory Ventilation", "eyebrow": "Part IV", "group": "Study Notes", "kind": "notes", "sections": [{"title": "15. HFOV Basics", "blocks": [{"t": "table", "head": ["<strong>Variable</strong>", "<strong>Main effect</strong>"], "rows": [["MAP", "Lung volume / oxygenation"], ["FiO2", "Oxygenation"], ["Amplitude (ΔP)", "CO2 clearance / oscillatory VT"], ["Frequency (Hz)", "Often inverse relation with VT; lowering Hz can increase CO2 clearance"], ["Inspiratory time %", "Device-specific oscillatory mechanics"]]}, {"t": "callout", "label": "HFOV EXAM TRAP", "title": "", "html": ["In conventional ventilation, increasing rate usually raises minute ventilation. In HFOV, lowering frequency often increases oscillatory VT and can improve CO2 clearance."], "fill": "17365D"}]}, {"title": "16. Oxygenation Index", "blocks": [{"t": "p", "html": "OI = (FiO2 × Mean Airway Pressure × 100) / PaO2."}, {"t": "table", "head": ["<strong>OI concept</strong>", "<strong>Interpretation</strong>"], "rows": [["&lt;15", "Mild/moderate oxygenation failure depending context"], ["15–25", "Significant disease; trend matters"], ["25–40", "Severe oxygenation failure"], ["≥40 persistent", "Historically prompts ECMO consideration in eligible term/near-term infants"]]}, {"t": "callout", "label": "CALCULATION PEARL", "title": "", "html": ["Use FiO2 as a fraction (0.60, not 60) because the formula already multiplies by 100."], "fill": "17365D"}]}]}, {"id": "part-5", "title": "Bronchopulmonary Dysplasia", "eyebrow": "Part V", "group": "Study Notes", "kind": "notes", "sections": [{"title": "17. What Is 'New BPD'?", "blocks": [{"t": "grid", "items": [{"label": "WHAT", "html": "Chronic lung disease of prematurity"}, {"label": "WHY", "html": "Immature lungs are injured during a critical developmental window"}, {"label": "HOW", "html": "Prematurity + oxygen + ventilation + inflammation + growth factors impair alveolar/vascular development"}, {"label": "RECOGNIZE", "html": "Prolonged support at 36 weeks PMA"}, {"label": "WHAT NEXT", "html": "Prevent injury early; evaluate severity, PH and discharge needs"}]}, {"t": "p", "html": "Modern BPD is dominated by arrested alveolarization and pulmonary vascular development rather than the severe fibroproliferative injury of the original 'old BPD' era."}]}, {"title": "18. BPD Definitions", "blocks": [{"t": "table", "head": ["<strong>Definition</strong>", "<strong>Key criteria</strong>", "<strong>Exam use</strong>"], "rows": [["NICHD 2001", "O2 for ≥28 days; severity at 36 wk PMA/discharge for &lt;32 wk infants", "Classic definition"], ["Jensen 2019", "Grade 1 = NC ≤2 L/min; Grade 2 = &gt;2 L/min or non-invasive positive pressure; Grade 3 = invasive MV at 36 wk PMA", "Modern outcome-based grading"], ["Contemporary concept", "Respiratory-support intensity at 36 wk PMA reflects chronic morbidity", "State definition used"]]}, {"t": "callout", "label": "JENSEN 2019 MUST KNOW", "title": "", "html": ["No BPD: no respiratory support at 36 weeks PMA. Grade 1: NC ≤2 L/min. Grade 2: NC &gt;2 L/min or non-invasive positive airway pressure. Grade 3: invasive MV."], "fill": "17365D"}]}, {"title": "19. BPD Pathogenesis & Risk Factors", "blocks": [{"t": "table", "head": ["<strong>Mechanism</strong>", "<strong>Examples</strong>"], "rows": [["Developmental immaturity", "Extreme prematurity, low birth weight"], ["Mechanical injury", "Volutrauma, atelectrauma, repeated derecruitment"], ["Oxygen toxicity", "High cumulative oxygen exposure"], ["Inflammation/infection", "Chorioamnionitis, sepsis, ventilator inflammation"], ["Pulmonary vascular injury", "Impaired angiogenesis, pulmonary hypertension"], ["Hemodynamic stress", "Selected significant PDA, fluid overload"], ["Nutrition/growth", "Poor postnatal growth"], ["Genetic susceptibility", "Interindividual variation"]]}]}, {"title": "20. BPD Prevention", "blocks": [{"t": "list", "ordered": false, "items": ["Antenatal corticosteroids and delivery in an appropriate perinatal center.", "CPAP/NIPPV rather than routine intubation in spontaneously breathing preterm infants.", "Early rescue surfactant with less-invasive administration when indicated.", "Minimize invasive ventilation; use lung-protective VTV/HFOV when needed.", "Caffeine to reduce apnea and facilitate extubation.", "Judicious oxygen targeting; European RDS suggests SpO2 90–94% in preterm infants receiving oxygen, alarms 89–95%.", "Optimize nutrition and growth.", "Selective postnatal corticosteroids in high-risk ventilator-dependent infants after individualized assessment."]}]}, {"title": "21. BPD Management & Pulmonary Hypertension", "blocks": [{"t": "table", "head": ["<strong>Problem</strong>", "<strong>Principle</strong>"], "rows": [["Ongoing support", "Lowest effective oxygen/pressure; avoid repeated atelectasis/hyperoxia"], ["Growth failure", "High-calorie/high-protein nutrition; manage fluid balance"], ["Pulmonary edema / selected severe BPD", "Diuretics may be used selectively"], ["Reactive airway component", "Bronchodilator trial only if response"], ["BPD-associated PH", "Echo screening in high-risk infants; optimize lung/cardiac physiology; specialist PH therapy if indicated"], ["Discharge", "Home oxygen if needed, caregiver education, immunization/RSV prevention per current eligibility, follow-up"]]}]}]}, {"id": "part-6", "title": "Neonatal Air-Leak Syndromes", "eyebrow": "Part VI", "group": "Study Notes", "kind": "notes", "sections": [{"title": "22. Air-Leak Spectrum", "blocks": [{"t": "table", "head": ["<strong>Air leak</strong>", "<strong>Typical clue</strong>", "<strong>Management principle</strong>"], "rows": [["Pneumothorax", "Sudden deterioration, asymmetry, transillumination; tension causes shock", "Unstable/tension: immediate decompression"], ["PIE", "Cystic/linear lucencies in ventilated preterm infant", "Reduce injurious VT/pressure; consider HFV/positioning"], ["Pneumomediastinum", "Spinnaker-sail sign; often less severe", "Observation/support if stable"], ["Pneumopericardium", "Air around heart; tamponade possible", "Emergency decompression if tamponade"], ["Systemic air embolism", "Rare catastrophic circulating air", "Resuscitation/support; prevention"]]}]}, {"title": "23. Tension Pneumothorax — Do Not Wait for X-ray", "blocks": [{"t": "callout", "label": "EMERGENCY RULE", "title": "", "html": ["A ventilated neonate with sudden severe hypoxemia/bradycardia, asymmetric chest findings and hemodynamic collapse should be treated for tension pneumothorax immediately if clinically suspected. Decompression precedes radiography in instability."], "fill": "17365D"}, {"t": "list", "ordered": true, "items": ["Call for help and provide cardiorespiratory support.", "Hand ventilate carefully while assessing ETT/circuit if necessary.", "If tension pneumothorax is strongly suspected and infant is unstable, perform emergency needle thoracentesis per neonatal protocol.", "Insert definitive intercostal drain when ongoing air leak requires it.", "Reduce ventilator pressures/VT after decompression and reassess lung disease."]}]}, {"title": "24. PIE", "blocks": [{"t": "list", "ordered": false, "items": ["Most common in very preterm infants with RDS exposed to positive-pressure ventilation.", "Gas dissects along perivascular/peribronchial interstitium.", "CXR: coarse linear or cystic lucencies extending from the hilum; focal or diffuse.", "Reduce VT/driving pressure and avoid overdistension.", "For unilateral PIE, affected-side-down positioning can help in selected infants.", "HFOV/other high-frequency ventilation is often considered for severe or refractory PIE."]}]}]}, {"id": "numbers", "title": "Must-Know Numbers", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Number / rule</strong>", "<strong>Meaning</strong>"], "rows": [["Initial PIP ~20–30 cm H2O", "Reasonable initial neonatal PPV range; adjust to effective ventilation"], ["CPAP ~6–8 cm H2O", "Common preterm RDS starting range"], ["VTV ~4–6 mL/kg", "Common neonatal target range; individualize"], ["SpO2 90–94%", "European RDS target in preterm infants receiving oxygen"], ["Alarm limits 89–95%", "European RDS recommendation"], ["PaCO2 &lt;35 mmHg", "Avoid during MV in preterm infants when possible"], ["pH &gt;7.22", "Permissive hypercapnia can be tolerated during weaning in European RDS guidance"], ["Caffeine citrate 20 mg/kg", "Common loading dose"], ["Caffeine citrate 5–10 mg/kg/day", "Common maintenance range"], ["OI = FiO2 × MAP ×100 / PaO2", "Oxygenation index"], ["Jensen Grade 1", "NC ≤2 L/min at 36 wk PMA"], ["Jensen Grade 2", "NC &gt;2 L/min or non-invasive positive airway pressure"], ["Jensen Grade 3", "Invasive MV at 36 wk PMA"]]}]}]}, {"id": "tables", "title": "Tables & Algorithms", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "Algorithm 1 — Hypercapnia on Conventional Ventilation", "h1": "Part VIII — Algorithms", "blocks": [{"t": "list", "ordered": true, "items": ["Confirm blood gas and clinical state; inspect waveform/VT.", "Check ETT position, patency, secretions, circuit and leak.", "Assess delivered VT and chest expansion.", "If VT is low, increase target VT or driving pressure cautiously depending mode.", "If VT is adequate but minute ventilation is low, consider increasing rate.", "If hyperinflation/air trapping is present, reduce rate and lengthen expiratory time rather than simply raising rate.", "Repeat gas; avoid overshooting into hypocapnia."]}]}, {"title": "Algorithm 2 — Hypoxemia on Ventilation", "h1": "", "blocks": [{"t": "list", "ordered": true, "items": ["Confirm oximetry signal and perfusion.", "Check ETT/circuit using DOPE.", "Increase FiO2 temporarily if needed for stabilization.", "Assess atelectasis versus overdistension versus shunt/PPHN.", "Optimize PEEP/MAP rather than repeatedly increasing PIP for a pure oxygenation problem.", "Consider surfactant, hemodynamic/PPHN therapy or HFOV according to cause.", "Reassess oxygenation, gas and hemodynamics."]}]}, {"title": "Algorithm 3 — Sudden Deterioration / Suspected Air Leak", "h1": "", "blocks": [{"t": "list", "ordered": true, "items": ["Call for help; assess HR, SpO2, perfusion and chest movement.", "Hand ventilate with a known-good device if equipment failure is possible.", "Check displacement and obstruction.", "Look for pneumothorax: asymmetry, transillumination/POCUS if available.", "If unstable tension pneumothorax is likely, decompress immediately — do not wait for X-ray.", "Place definitive chest drainage if ongoing pneumothorax requires it.", "Reduce injurious ventilator settings and reassess for PIE/recurrent leak."]}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — RDS after surfactant", "blocks": [{"t": "p", "html": "A 27-week infant on pressure control receives surfactant. VT rises from 5 to 9 mL/kg at the same PIP and PaCO2 falls rapidly."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Compliance improved.", "Fixed pressure is now delivering excessive VT.", "Reduce inspiratory pressure or retune VTV."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["Rapid compliance change after surfactant is a classic reason to favor VTV."], "fill": "7F6000"}]}, {"title": "Case 2 — Hypercapnia with obstruction", "blocks": [{"t": "p", "html": "Ventilated preterm infant: pH 7.20, PaCO2 72. VT falling; secretions visible."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Do not reflexively increase pressure.", "Suction/check ETT.", "Reassess VT and gas."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["Treat mechanical causes before escalating pressure."], "fill": "7F6000"}]}, {"title": "Case 3 — Oxygenation failure", "blocks": [{"t": "p", "html": "PaO2 low despite acceptable PaCO2. CXR: diffuse atelectasis and low volume."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["This is oxygenation/recruitment failure.", "Optimize FiO2 acutely then PEEP/MAP.", "Rate is not the primary fix."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["Oxygenation and ventilation are different problems."], "fill": "7F6000"}]}, {"title": "Case 4 — Air trapping", "blocks": [{"t": "p", "html": "Evolving BPD on high rate. Expiratory flow has not returned to baseline; CXR hyperinflated."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Dynamic hyperinflation/auto-PEEP.", "Reduce rate or Ti to lengthen expiration.", "Address obstruction."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["Always inspect expiratory time in long time-constant disease."], "fill": "7F6000"}]}, {"title": "Case 5 — Mixed acidosis", "blocks": [{"t": "p", "html": "pH 7.10, PaCO2 65, HCO3 19 with poor perfusion and high lactate."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Respiratory acidosis.", "Metabolic acidosis.", "Improve ventilation and shock/perfusion."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["A severely low pH can have more than one driver."], "fill": "7F6000"}]}, {"title": "Case 6 — HFOV CO2 problem", "blocks": [{"t": "p", "html": "On HFOV, oxygenation acceptable but PaCO2 75; chest wiggle modest."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Ventilation depends on amplitude/oscillatory VT.", "Increase amplitude; lowering frequency may also help.", "Do not increase FiO2 for CO2."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["HFOV frequency behaves differently from conventional rate."], "fill": "7F6000"}]}, {"title": "Case 7 — BPD classification", "blocks": [{"t": "p", "html": "At 36 weeks PMA an extremely preterm infant requires CPAP."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Jensen Grade 2.", "FiO2 is not required for Jensen grading.", "Support predicts later morbidity."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["Know support-based BPD classification."], "fill": "7F6000"}]}, {"title": "Case 8 — BPD-associated PH", "blocks": [{"t": "p", "html": "Severe BPD infant has rising O2 need, poor growth and echo RV pressure elevation."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Suspect BPD-PH.", "Optimize oxygenation/lung disease and assess cardiac contributors.", "Coordinate PH management."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["Unexplained deterioration in severe BPD should trigger PH evaluation."], "fill": "7F6000"}]}, {"title": "Case 9 — Tension pneumothorax", "blocks": [{"t": "p", "html": "Ventilated 29-week infant suddenly cyanotic/bradycardic with asymmetric chest expansion and hypotension."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["Treat as tension pneumothorax.", "Immediate decompression before radiography.", "Then drain and reduce injurious support."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["Do not wait for X-ray in tension physiology."], "fill": "7F6000"}]}, {"title": "Case 10 — PIE", "blocks": [{"t": "p", "html": "A 25-week infant on high pressures develops cystic/linear lucencies radiating from hila."}, {"t": "p", "html": "Reasoning:"}, {"t": "list", "ordered": false, "items": ["PIE.", "Reduce VT/driving pressure; consider HFV/positioning.", "Look for associated pneumothorax."]}, {"t": "callout", "label": "CASE PEARL", "title": "", "html": ["PIE is a ventilator-injury signal."], "fill": "7F6000"}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Station</strong>", "<strong>Data</strong>", "<strong>Interpretation</strong>"], "rows": [["Station 1", "pH 7.19 / PaCO2 68 / HCO3 25", "Acute respiratory acidosis."], ["Station 2", "pH 7.49 / PaCO2 28 / HCO3 21", "Respiratory alkalosis; reduce excessive minute ventilation."], ["Station 3", "pH 7.12 / PaCO2 58 / HCO3 18", "Mixed respiratory + metabolic acidosis."], ["Station 4", "Expiratory flow does not reach baseline", "Air trapping/auto-PEEP."], ["Station 5", "Same PIP, VT jumps after surfactant", "Compliance improved; pressure mode may overdeliver VT."], ["Station 6", "Pleural line + absent peripheral markings + mediastinal shift", "Tension pneumothorax if unstable."], ["Station 7", "Coarse linear/cystic lucencies from hila", "PIE."], ["Station 8", "FiO2 0.8, MAP 16, PaO2 50", "OI = 25.6."]]}]}]}, {"id": "pearls", "title": "Pearls & Traps", "group": "Practice", "kind": "pearls", "sections": [{"title": "25 Exam Pearls", "blocks": [{"t": "list", "ordered": false, "items": ["Oxygenation is mainly FiO2 + MAP/recruitment; ventilation is mainly effective VT × rate.", "Volutrauma may be more damaging than high pressure by itself.", "After surfactant, the same pressure can suddenly deliver excessive VT.", "Time constant = resistance × compliance.", "Long time constants need more expiratory time.", "VTV is a key lung-protective strategy in preterm infants.", "Avoid invasive ventilation when effective CPAP/NIPPV is possible.", "Initial neonatal PPV PIP around 20–30 cm H2O is reasonable; titrate to effect.", "CPAP around 6–8 cm H2O is a common preterm starting range.", "VTV target VT often begins around 4–6 mL/kg but is individualized.", "Permissive hypercapnia may be safer than excessive ventilation when pH is acceptable.", "Avoid PaCO2 below ~35 mmHg in ventilated preterm infants when possible.", "Troubleshoot ETT/circuit before escalating support for unexplained hypercapnia.", "DOPE is a rapid sudden-deterioration framework.", "HFOV MAP mainly controls oxygenation; amplitude mainly controls ventilation.", "Lowering HFOV frequency can improve CO2 clearance.", "Use FiO2 as a fraction in OI.", "Jensen Grade 1 = NC ≤2 L/min at 36 wk PMA.", "Jensen Grade 2 = NC &gt;2 L/min or non-invasive positive pressure.", "Jensen Grade 3 = invasive MV.", "Modern BPD is impaired alveolar and vascular development.", "Minimizing invasive ventilation exposure is central to BPD prevention.", "BPD-associated PH is a major complication.", "Tension pneumothorax in instability: decompress before X-ray.", "PIE should trigger immediate lung-protective reassessment."]}]}, {"title": "15 Traps", "blocks": [{"t": "list", "ordered": false, "items": ["Increasing rate for isolated hypoxemia.", "Increasing FiO2 for isolated hypercapnia.", "Using PIP alone as a surrogate for lung injury while ignoring VT.", "Failing to reduce pressure after surfactant improves compliance.", "Causing hypocapnia while chasing a normal PaCO2.", "Applying conventional rate logic directly to HFOV frequency.", "Entering FiO2 as 80 instead of 0.80 in OI.", "Missing auto-PEEP because only peak pressures are reviewed.", "Using routine deep sedation for every ventilated preterm infant.", "Assuming BPD is defined only by FiO2.", "Confusing Jensen Grade 2 with invasive ventilation.", "Treating BPD-PH only by escalating FiO2.", "Waiting for X-ray in unstable tension pneumothorax.", "Treating pneumomediastinum as if it always needs drainage.", "Continuing injurious settings after an air leak is drained."]}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "revision", "title": "Rapid Revision", "group": "Revise", "kind": "revision", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["Separate oxygenation from ventilation before touching the ventilator.", "PEEP/MAP recruit lung and primarily improve oxygenation.", "Effective VT and rate determine alveolar ventilation.", "Time constant = resistance × compliance.", "Long time constant → incomplete exhalation/air trapping risk.", "Same PIP can deliver very different VT as compliance changes.", "Surfactant can rapidly reduce pressure requirement.", "VTV commonly begins around 4–6 mL/kg and is individualized.", "Spontaneously breathing preterm infants should usually start with CPAP rather than routine intubation.", "Initial neonatal PPV PIP ~20–30 cm H2O is reasonable; titrate to response.", "European RDS CPAP starting pressure ~6–8 cm H2O.", "European RDS SpO2 target 90–94% on oxygen; alarms 89–95%.", "Avoid PaCO2 &lt;35 mmHg during MV in preterm infants when possible.", "Permissive hypercapnia during weaning can be acceptable if pH &gt;7.22.", "Caffeine citrate load 20 mg/kg; maintenance 5–10 mg/kg/day.", "DOPE: displacement, obstruction, pneumothorax, equipment.", "HFOV MAP → oxygenation.", "HFOV amplitude → ventilation.", "Lower HFOV frequency often increases VT/CO2 clearance.", "OI = FiO2 × MAP ×100 / PaO2.", "Persistent OI ~40 in eligible term/near-term infant is severe and may prompt ECMO evaluation.", "Jensen Grade 1: NC ≤2 L/min at 36 wk PMA.", "Jensen Grade 2: NC &gt;2 L/min or non-invasive positive pressure.", "Jensen Grade 3: invasive MV.", "Modern BPD = alveolar simplification + pulmonary vascular dysdevelopment.", "Minimize invasive ventilation to prevent BPD.", "Severe BPD can cause pulmonary hypertension.", "Tension pneumothorax with instability → immediate decompression before X-ray.", "PIE = air dissecting within pulmonary interstitium.", "After an air leak, reduce injurious ventilation as physiology allows."]}]}]}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["What are the primary ventilator determinants of oxygenation?", "What determines CO2 clearance?", "Define compliance and time constant.", "Why can high rate worsen long time-constant disease?", "How does raising PEEP with fixed PIP affect driving pressure?", "What can happen to VT after surfactant if PIP is unchanged?", "Why is VTV favored in preterm infants?", "What VT range is commonly used initially in VTV?", "When is permissive hypercapnia acceptable?", "Why should hypocapnia be avoided?", "State DOPE.", "Which HFOV variable controls oxygenation?", "Which HFOV variable controls ventilation?", "What happens when HFOV frequency is reduced?", "Write the OI formula.", "Calculate OI for FiO2 0.6, MAP 14, PaO2 56.", "List Jensen BPD Grades 1–3.", "Describe modern BPD pathogenesis.", "List six BPD-prevention strategies.", "What suggests BPD-associated PH?", "How do pneumothorax and PIE differ?", "When must pneumothorax be decompressed before imaging?", "What ventilator changes reduce PIE risk?", "Use Winter formula for HCO3 10.", "Interpret pH 7.38, PaCO2 62, HCO3 36."]}]}]}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "K/C/R/G/S Error Notebook", "h1": "K/C/R/G/S Error Notebook", "blocks": [{"t": "table", "head": ["<strong>Field</strong>", "<strong>Your entry</strong>"], "rows": [["Total score", "____ / 75"], ["Basic errors", "____"], ["Conceptual errors", "____"], ["Clinical/Application errors", "____"], ["High-Difficulty errors", "____"], ["Integrated errors", "____"], ["K — Knowledge gap", "Q: ____ | Fact missed: __________________"], ["C — Concept gap", "Q: ____ | Concept misunderstood: __________________"], ["R — Reasoning error", "Q: ____ | Wrong branch/sequence: __________________"], ["G — Guessing", "Q: ____ | Why I guessed: __________________"], ["S — Careless error", "Q: ____ | Prevention trigger: __________________"], ["Top 5 weak topics", "1.___ 2.___ 3.___ 4.___ 5.___"]]}]}, {"title": "R1 / R2 / R3 Revision", "h1": "", "blocks": [{"t": "table", "head": ["<strong>Cycle</strong>", "<strong>When</strong>", "<strong>Task</strong>"], "rows": [["R1", "24 hours", "Rebuild oxygenation-vs-ventilation, DOPE, HFOV controls and ABG method; redo wrong/guessed MCQs."], ["R2", "7 days", "20 mixed ventilation/ABG/BPD/air-leak questions; recalculate OI and compensation rules."], ["R3", "21 days", "Retest K/C/R errors; reproduce BPD grading and sudden-deterioration algorithms; repeat 10 cases."]]}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "Guideline & Evidence References — Verified 04 Oct 2026", "h1": "Guideline & Evidence References — Verified 04 Oct 2026", "blocks": [{"t": "list", "ordered": true, "items": ["American Heart Association / American Academy of Pediatrics. 2025 Guidelines for Neonatal Resuscitation.", "International Liaison Committee on Resuscitation. Neonatal Life Support: 2025 Consensus on Science With Treatment Recommendations.", "Sweet DG, et al. European Consensus Guidelines on the Management of Respiratory Distress Syndrome: 2022 Update. Neonatology. 2023;120:3–23.", "Jensen EA, et al. The Diagnosis of Bronchopulmonary Dysplasia in Very Preterm Infants: An Evidence-based Approach. Am J Respir Crit Care Med. 2019;200:751–759.", "Device-specific ventilator behavior, local NICU protocols and bedside physiology supersede generic educational settings."]}]}, {"title": "Document QA Summary", "h1": "Document QA Summary", "blocks": [{"t": "table", "head": ["<strong>Check</strong>", "<strong>Result</strong>"], "rows": [["Total MCQs", "75"], ["Basic/Recall", "8"], ["Conceptual", "12"], ["Clinical/Application", "25"], ["High-Difficulty", "22"], ["Integrated/Rank-Differentiating", "8"], ["Answer A", "19"], ["Answer B", "19"], ["Answer C", "19"], ["Answer D", "18"], ["Unique exam pearls", "75"], ["Unique Why This Question Matters", "75"]]}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 15, "n": 15}, {"k": 2, "from": 16, "to": 30, "n": 15}, {"k": 3, "from": 31, "to": 45, "n": 15}, {"k": 4, "from": 46, "to": 60, "n": 15}, {"k": 5, "from": 61, "to": 75, "n": 15}], "mcqCount": 75};
